namespace RonSijm.FluidHumidifier.Factories.MGN;

public class NetworkMigrationDefinitionFactory(string resourceName = null, Action<Humidifier.MGN.NetworkMigrationDefinition> factoryAction = null) : ResourceFactory<Humidifier.MGN.NetworkMigrationDefinition>(resourceName)
{

    internal List<InnerNetworkMigrationDefinitionSourceConfigurationFactory> SourceConfigurationsFactories { get; set; } = [];

    internal InnerNetworkMigrationDefinitionTargetS3ConfigurationFactory TargetS3ConfigurationFactory { get; set; }

    internal InnerNetworkMigrationDefinitionTargetNetworkFactory TargetNetworkFactory { get; set; }

    protected override Humidifier.MGN.NetworkMigrationDefinition Create()
    {
        var networkMigrationDefinitionResult = CreateNetworkMigrationDefinition();
        factoryAction?.Invoke(networkMigrationDefinitionResult);

        return networkMigrationDefinitionResult;
    }

    private Humidifier.MGN.NetworkMigrationDefinition CreateNetworkMigrationDefinition()
    {
        var networkMigrationDefinitionResult = new Humidifier.MGN.NetworkMigrationDefinition
        {
            GivenName = InputResourceName,
        };

        return networkMigrationDefinitionResult;
    }
    public override void CreateChildren(Humidifier.MGN.NetworkMigrationDefinition result)
    {
        base.CreateChildren(result);

        result.SourceConfigurations = SourceConfigurationsFactories.Any() ? SourceConfigurationsFactories.Select(x => x.Build()).ToList() : null;
        result.TargetS3Configuration ??= TargetS3ConfigurationFactory?.Build();
        result.TargetNetwork ??= TargetNetworkFactory?.Build();
    }

} // End Of Class

